alter table public.company_books add constraint company_books_company_book_key UNIQUE (company, book);
alter table public.entry_links add constraint entry_links_token_key UNIQUE (token);
alter table public.exp_attendance add constraint exp_attendance_staff_id_day_key UNIQUE (staff_id, day);
alter table public.exp_budgets add constraint exp_budgets_source_head_key UNIQUE (source, head);
alter table public.salary_slips add constraint salary_slips_person_kind_person_id_month_key UNIQUE (person_kind, person_id, month);
alter table public.transport_salaries add constraint transport_salaries_driver_id_month_key UNIQUE (driver_id, month);
alter table public.acc_items add constraint acc_items_side_check CHECK ((side = ANY (ARRAY['asset'::text, 'liability'::text, 'equity'::text])));
alter table public.bill_accounts add constraint bill_accounts_payment_type_check CHECK ((payment_type = ANY (ARRAY['Prepaid'::text, 'Postpaid'::text])));
alter table public.bill_payments add constraint bill_payments_amount_check CHECK ((amount >= (0)::numeric));
alter table public.chat_messages add constraint chat_messages_kind_check CHECK ((kind = ANY (ARRAY['text'::text, 'photo'::text, 'voice'::text])));
alter table public.chat_rooms add constraint chat_rooms_kind_check CHECK ((kind = ANY (ARRAY['dm'::text, 'group'::text])));
alter table public.company_docs add constraint company_docs_kind_check CHECK ((kind = ANY (ARRAY['invoice'::text, 'receipt'::text])));
alter table public.doc_checklist add constraint doc_checklist_section_check CHECK ((section = ANY (ARRAY['employee'::text, 'car'::text, 'heavy'::text, 'govt'::text, 'company'::text])));
alter table public.exp_attendance add constraint exp_attendance_mark_check CHECK ((mark = ANY (ARRAY['P'::text, 'A'::text, 'L'::text, 'H'::text])));
alter table public.items add constraint items_min_qty_check CHECK ((min_qty >= (0)::numeric));
alter table public.items add constraint items_per_pack_check CHECK ((per_pack > (0)::numeric));
alter table public.items add constraint items_price_check CHECK ((price >= (0)::numeric));
alter table public.items add constraint items_quantity_check CHECK ((quantity >= (0)::numeric));
alter table public.petty_cash add constraint petty_cash_amount_check CHECK ((amount > (0)::numeric));
alter table public.petty_cash add constraint petty_cash_kind_check CHECK ((kind = ANY (ARRAY['in'::text, 'out'::text])));
alter table public.salary_credits add constraint salary_credits_person_kind_check CHECK ((person_kind = ANY (ARRAY['staff'::text, 'driver'::text])));
alter table public.salary_slips add constraint salary_slips_person_kind_check CHECK ((person_kind = ANY (ARRAY['staff'::text, 'driver'::text])));
alter table public.salary_slips add constraint salary_slips_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'approved'::text])));
alter table public.stock_moves add constraint stock_moves_move_type_check CHECK ((move_type = ANY (ARRAY['in'::text, 'out'::text])));
alter table public.stock_moves add constraint stock_moves_qty_check CHECK ((qty > (0)::numeric));
alter table public.transport_invoices add constraint transport_invoices_kind_check CHECK ((kind = ANY (ARRAY['invoice'::text, 'interim'::text, 'tax'::text])));
alter table public.transport_vehicles add constraint transport_vehicles_ownership_check CHECK ((ownership = ANY (ARRAY['Own'::text, 'Rent'::text])));
alter table public.transport_vehicles add constraint transport_vehicles_part_check CHECK ((part = ANY (ARRAY['Unit'::text, 'Trailer'::text])));
alter table public.vehicle_maintenance add constraint vehicle_maintenance_payment_method_check CHECK ((payment_method = ANY (ARRAY['PDC'::text, 'Bank Transfer'::text])));
alter table public.vehicle_maintenance add constraint vehicle_maintenance_status_check CHECK ((status = ANY (ARRAY['Pending'::text, 'Paid'::text, 'Done'::text])));
alter table public.acc_txns add constraint acc_txns_account_id_fkey FOREIGN KEY (account_id) REFERENCES acc_accounts(id) ON DELETE CASCADE;
alter table public.alert_dismissals add constraint alert_dismissals_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
alter table public.bill_payments add constraint bill_payments_account_id_fkey FOREIGN KEY (account_id) REFERENCES bill_accounts(id) ON DELETE CASCADE;
alter table public.chat_members add constraint chat_members_room_id_fkey FOREIGN KEY (room_id) REFERENCES chat_rooms(id) ON DELETE CASCADE;
alter table public.chat_members add constraint chat_members_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
alter table public.chat_messages add constraint chat_messages_room_id_fkey FOREIGN KEY (room_id) REFERENCES chat_rooms(id) ON DELETE CASCADE;
alter table public.chat_messages add constraint chat_messages_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
alter table public.company_access add constraint company_access_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
alter table public.entry_links add constraint entry_links_driver_id_fkey FOREIGN KEY (driver_id) REFERENCES transport_drivers(id) ON DELETE CASCADE;
alter table public.exp_attendance add constraint exp_attendance_staff_id_fkey FOREIGN KEY (staff_id) REFERENCES exp_staff(id) ON DELETE CASCADE;
alter table public.items add constraint items_category_id_fkey FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE CASCADE;
alter table public.stock_moves add constraint stock_moves_item_id_fkey FOREIGN KEY (item_id) REFERENCES items(id) ON DELETE CASCADE;
alter table public.transport_drivers add constraint transport_drivers_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE SET NULL;
alter table public.transport_entries add constraint transport_entries_allowance_salary_id_fkey FOREIGN KEY (allowance_salary_id) REFERENCES transport_salaries(id) ON DELETE SET NULL;
alter table public.transport_entries add constraint transport_entries_driver_id_fkey FOREIGN KEY (driver_id) REFERENCES transport_drivers(id) ON DELETE CASCADE;
alter table public.transport_extras add constraint transport_extras_driver_id_fkey FOREIGN KEY (driver_id) REFERENCES transport_drivers(id) ON DELETE CASCADE;
alter table public.transport_profit_taken add constraint transport_profit_taken_driver_id_fkey FOREIGN KEY (driver_id) REFERENCES transport_drivers(id) ON DELETE CASCADE;
alter table public.transport_salaries add constraint transport_salaries_driver_id_fkey FOREIGN KEY (driver_id) REFERENCES transport_drivers(id) ON DELETE CASCADE;
alter table public.transport_vehicles add constraint transport_vehicles_driver_id_fkey FOREIGN KEY (driver_id) REFERENCES transport_drivers(id) ON DELETE SET NULL;
alter table public.user_designations add constraint user_designations_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
alter table public.user_events add constraint user_events_session_id_fkey FOREIGN KEY (session_id) REFERENCES user_sessions(id) ON DELETE CASCADE;
alter table public.vehicle_maintenance add constraint vehicle_maintenance_vehicle_id_fkey FOREIGN KEY (vehicle_id) REFERENCES transport_vehicles(id) ON DELETE CASCADE;

CREATE INDEX acc_txns_account_idx ON public.acc_txns USING btree (account_id, txn_date);
CREATE INDEX audit_log_at_idx ON public.audit_log USING btree (at DESC);
CREATE INDEX audit_log_user_idx ON public.audit_log USING btree (user_id, at DESC);
CREATE INDEX bill_payments_account_idx ON public.bill_payments USING btree (account_id);
CREATE INDEX chat_messages_room_at ON public.chat_messages USING btree (room_id, created_at DESC);
CREATE INDEX doc_checklist_section ON public.doc_checklist USING btree (section, sort);
CREATE INDEX exp_attendance_company_day ON public.exp_attendance USING btree (company, day);
CREATE INDEX exp_entries_company ON public.exp_entries USING btree (company, entry_date);
CREATE INDEX exp_entries_date ON public.exp_entries USING btree (entry_date);
CREATE INDEX exp_entries_source_idx ON public.exp_entries USING btree (source, source_id);
CREATE INDEX items_category_idx ON public.items USING btree (category_id);
CREATE INDEX petty_cash_co_date_idx ON public.petty_cash USING btree (company, date);
CREATE INDEX stock_moves_created_idx ON public.stock_moves USING btree (created_at DESC);
CREATE INDEX stock_moves_item_idx ON public.stock_moves USING btree (item_id);
CREATE INDEX transport_entries_allow_sal ON public.transport_entries USING btree (allowance_salary_id);
CREATE INDEX transport_entries_driver_date ON public.transport_entries USING btree (driver_id, entry_date);
CREATE INDEX transport_profit_taken_driver ON public.transport_profit_taken USING btree (driver_id, taken_on);
CREATE INDEX user_events_session_idx ON public.user_events USING btree (session_id, at);
CREATE INDEX user_events_user_idx ON public.user_events USING btree (user_id, at DESC);
CREATE INDEX user_sessions_seen_idx ON public.user_sessions USING btree (last_seen DESC);
CREATE INDEX user_sessions_user_idx ON public.user_sessions USING btree (user_id, started_at DESC);
CREATE UNIQUE INDEX bill_accounts_company_name_key ON public.bill_accounts USING btree (COALESCE(company, ''::text), name);
CREATE UNIQUE INDEX categories_company_name_key ON public.categories USING btree (COALESCE(company, ''::text), name);
CREATE UNIQUE INDEX chat_rooms_group_company ON public.chat_rooms USING btree (company) WHERE (kind = 'group'::text);
CREATE UNIQUE INDEX transport_drivers_user_idx ON public.transport_drivers USING btree (user_id) WHERE (user_id IS NOT NULL);
